package com.shale.data.dao;

import java.sql.*;
import java.time.Instant;
import java.util.*;
import com.shale.core.dto.UserReleaseStateView;
import com.shale.core.model.*;
import com.shale.core.runtime.DbSessionProvider;

/** Transactional, current-user-only release announcement state. */
public final class UserReleaseStateDao {
	private static final String STATE_SELECT="""
		SELECT s.Id,s.ShaleClientId,s.UserId,s.ClientType,s.ReleaseChannel,s.ApplicationReleaseId,
		 r.MajorVersion,r.MinorVersion,r.BuildVersion,s.AcknowledgedAt,s.RowVer
		FROM dbo.UserReleaseState s JOIN dbo.ApplicationReleases r ON r.Id=s.ApplicationReleaseId
		WHERE s.ShaleClientId=? AND s.UserId=? AND s.ClientType=? AND s.ReleaseChannel=?""";
	private final DbSessionProvider db;
	public UserReleaseStateDao(DbSessionProvider db){this.db=Objects.requireNonNull(db,"db");}
	public Optional<UserReleaseStateView> findCurrent(int tenant,int user,ClientType type,ReleaseChannel channel){scope(tenant,user,type,channel);try(Connection c=db.requireConnection()){verifyActor(c,tenant,user);return load(c,tenant,user,type,channel,false);}catch(SQLException e){throw failure("read",e);}}
	public UserReleaseStateView acknowledge(int tenant,int user,ClientType type,ReleaseChannel channel,long releaseId,byte[] expected){scope(tenant,user,type,channel);if(releaseId<=0)throw new IllegalArgumentException("targetReleaseId must be positive");Connection c=db.requireConnection();try(c){boolean oldAuto=c.getAutoCommit();c.setAutoCommit(false);try{verifyActor(c,tenant,user);Release target=release(c,releaseId);if(target.status!=PublicationStatus.PUBLISHED)throw new IllegalArgumentException("Only published releases may be acknowledged.");if(target.channel!=channel)throw new IllegalArgumentException("Target release channel does not match release state scope.");Optional<UserReleaseStateView> old=load(c,tenant,user,type,channel,true);if(old.isPresent()){int order=target.version.compareTo(old.get().version());if(order<0)throw new IllegalArgumentException("Acknowledged release cannot move backwards.");if(order==0){c.commit();return old.get();}if(expected==null||!Arrays.equals(expected,old.get().rowVersion()))throw new IllegalStateException("Release state changed. Reload and try again.");update(c,old.get().id(),tenant,user,releaseId,expected);}else{if(expected!=null&&expected.length>0)throw new IllegalStateException("Release state changed. Reload and try again.");insert(c,tenant,user,type,channel,releaseId);}UserReleaseStateView result=load(c,tenant,user,type,channel,false).orElseThrow();c.commit();return result;}catch(SQLException|RuntimeException e){rollback(c);throw e;}finally{try{c.setAutoCommit(oldAuto);}catch(SQLException ignored){}}}catch(SQLException e){if(e.getErrorCode()==2601||e.getErrorCode()==2627)throw new IllegalStateException("Release state was created concurrently. Reload and try again.",e);throw failure("acknowledge",e);}}
	private static void verifyActor(Connection c,int t,int u)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT 1 FROM dbo.Users WHERE id=? AND ShaleClientId=? AND COALESCE(is_deleted,0)=0 AND COALESCE(IsRemoved,0)=0 AND CAST(SESSION_CONTEXT(N'ShaleClientId') AS int)=? AND CAST(SESSION_CONTEXT(N'PrincipalUserId') AS int)=?")){p.setInt(1,u);p.setInt(2,t);p.setInt(3,t);p.setInt(4,u);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SecurityException("An authenticated active same-tenant user is required.");}}}
	private static Release release(Connection c,long id)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT MajorVersion,MinorVersion,BuildVersion,ReleaseChannel,PublicationStatus FROM dbo.ApplicationReleases WHERE Id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Target release does not exist.");return new Release(new SemanticVersion(r.getInt(1),r.getInt(2),r.getInt(3)),value(ReleaseChannel.class,r.getString(4)),value(PublicationStatus.class,r.getString(5)));}}}
	private static Optional<UserReleaseStateView> load(Connection c,int t,int u,ClientType type,ReleaseChannel ch,boolean lock)throws SQLException{String sql=lock?STATE_SELECT.replace("UserReleaseState s JOIN","UserReleaseState s WITH (UPDLOCK,HOLDLOCK) JOIN"):STATE_SELECT;try(PreparedStatement p=c.prepareStatement(sql)){p.setInt(1,t);p.setInt(2,u);p.setString(3,type.name());p.setString(4,ch.name());try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(map(r)):Optional.empty();}}}
	private static void insert(Connection c,int t,int u,ClientType type,ReleaseChannel ch,long release)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT dbo.UserReleaseState(ShaleClientId,UserId,ClientType,ReleaseChannel,ApplicationReleaseId,AcknowledgedAt,CreatedAt,UpdatedAt) VALUES(?,?,?,?,?,SYSUTCDATETIME(),SYSUTCDATETIME(),SYSUTCDATETIME())")){p.setInt(1,t);p.setInt(2,u);p.setString(3,type.name());p.setString(4,ch.name());p.setLong(5,release);p.executeUpdate();}}
	private static void update(Connection c,long id,int t,int u,long release,byte[] rv)throws SQLException{try(PreparedStatement p=c.prepareStatement("UPDATE dbo.UserReleaseState SET ApplicationReleaseId=?,AcknowledgedAt=SYSUTCDATETIME(),UpdatedAt=SYSUTCDATETIME() WHERE Id=? AND ShaleClientId=? AND UserId=? AND RowVer=?")){p.setLong(1,release);p.setLong(2,id);p.setInt(3,t);p.setInt(4,u);p.setBytes(5,rv);if(p.executeUpdate()!=1)throw new IllegalStateException("Release state changed. Reload and try again.");}}
	private static UserReleaseStateView map(ResultSet r)throws SQLException{return new UserReleaseStateView(r.getLong(1),r.getInt(2),r.getInt(3),value(ClientType.class,r.getString(4)),value(ReleaseChannel.class,r.getString(5)),r.getLong(6),new SemanticVersion(r.getInt(7),r.getInt(8),r.getInt(9)),r.getTimestamp(10).toInstant(),r.getBytes(11));}
	private static void scope(int t,int u,Object type,Object channel){if(t<=0||u<=0)throw new SecurityException("An authenticated tenant user is required.");Objects.requireNonNull(type,"clientType");Objects.requireNonNull(channel,"releaseChannel");}
	private static <E extends Enum<E>>E value(Class<E> c,String s){try{return Enum.valueOf(c,s);}catch(RuntimeException e){throw new IllegalStateException("Unknown "+c.getSimpleName()+" database value: "+s,e);}}
	private static void rollback(Connection c){try{c.rollback();}catch(SQLException ignored){}}
	private static IllegalStateException failure(String op,SQLException e){return new IllegalStateException("Failed to "+op+" user release state",e);}
	private record Release(SemanticVersion version,ReleaseChannel channel,PublicationStatus status){}
}
